import { CHAIN, CONTRACTS } from './chain-config.js';
import { readLiveDiceRunRecord, RECORD_KIND_DICE_RUN } from './records.js';
import { chainClient } from '../chain/client.js';
import { eventFacts } from '../chain/facts.js';
import { previousEvents } from '../chain/event-store.js';

// Exported from verified BigRecordUpdated events. A hint only: a different
// deployment or record value cannot inherit an old holder from this file.
let snapshotPromise;
export function applyBountyHolderSnapshot(state, snapshot) {
  if (Number(snapshot?.chainId) !== Number(CHAIN.id)
    || String(snapshot?.coinflip).toLowerCase() !== String(CONTRACTS.COINFLIP).toLowerCase()
    || !Array.isArray(snapshot?.records)) return state;
  return { ...state, records: state.records.map(record => {
    if (!record.held) return record;
    const hint = snapshot.records.find(row => Number(row.kind) === record.kind
      && String(row.value) === String(record.value) && /^0x[0-9a-f]{40}$/i.test(row.player));
    if (!hint) return record;
    return { ...record, player: hint.player.toLowerCase(), transactionHash: hint.transactionHash,
      blockNumber: hint.blockNumber, logIndex: hint.logIndex };
  }) };
}

export async function readSavedBountyHolders(state) {
  snapshotPromise ??= fetch('/app/assets/bounty-holders.json', { signal: AbortSignal.timeout(4000) })
    .then(response => response.ok ? response.json() : null)
    .catch(() => { snapshotPromise = null; return null; });
  return applyBountyHolderSnapshot(state, await snapshotPromise);
}

/**
 * Where the current Dice Run mark was set, without rebuilding day history. Coinflip stamps
 * `recordDayDiceRun = today` on every Dice Run ratchet and nowhere else after deploy
 * (CoinflipCore.sol:402, :1291), and the mark only rises, so its BigRecordUpdated is the newest
 * kind-4 record event. On a deployment whose logical days track the wall clock it was emitted
 * no earlier than that day's wall-clock start (ChainClient.dayOf's inverse plus the block
 * interval), so a short forward scan from there finds it. (activityRange(day) found the same event but re-indexed
 * every logical day since: ~70 s for a record a few days old.)
 */
export async function findDiceRunRecordLog(record) {
  const day = Number(record?.clockDay);
  if (!Number.isSafeInteger(day) || day < 1) return null;
  const client = chainClient();
  const s = await client.snapshot();
  const { anchor, period, deployDayBoundary } = client.clock ?? {};
  const blockSeconds = Number(client.blockSeconds) || 2;
  if (![anchor, period, deployDayBoundary].every(Number.isFinite)) return null;
  const dayStart = anchor + (day - 1 + deployDayBoundary) * period;
  // Missed slots only make the estimate earlier, which is still a valid lower bound.
  const fromBlock = Math.max(Number(client.chain.deployBlock) || 0,
    s.block.number - Math.ceil(Math.max(0, s.block.timestamp - dayStart) / blockSeconds) - 30);
  const rows = await eventFacts(s, ['BigRecordUpdated'], {
    contract: 'COINFLIP', filters: { kind: RECORD_KIND_DICE_RUN }, fromBlock, toBlock: s.block.number,
  });
  // The day-clock estimate is a fast path. A deployment whose logical days ran ahead of the wall
  // clock (testnet) puts the event before it, so fall back to walking back from the head for the
  // newest kind-4 event: always correct, and paid once per record because the rail saves the
  // result in the records cache.
  const hit = rows.at(-1) ?? (await previousEvents(client, 'COINFLIP', 'BigRecordUpdated',
    { blockNumber: s.block.number, logIndex: Number.MAX_SAFE_INTEGER }, { filters: { kind: RECORD_KIND_DICE_RUN } })).at(-1);
  return hit ? { transactionHash: hit.transactionHash, blockNumber: hit.blockNumber, logIndex: hit.logIndex } : null;
}

/**
 * The Dice Run replay link, looked up only when the player opens it. A record that already
 * carries its transaction (saved in the records cache after the first open) needs just the
 * receipt; otherwise the mark's stamped day says where to look.
 */
export async function readBountyReplay(record) {
  if (!record?.player) return null;
  let located = record;
  if (!located.transactionHash) {
    const found = await findDiceRunRecordLog(record).catch(() => null);
    if (!found) return null;
    located = { ...record, ...found };
  }
  const replay = await readLiveDiceRunRecord({ payload: { diceRun: located } });
  return replay ? { ...replay, transactionHash: located.transactionHash, blockNumber: located.blockNumber, logIndex: located.logIndex } : null;
}
